function tituloVaga(v){return v.cargo||v.titulo||'Vaga'}function preencherAreasPortal(){const el=$('#filtroArea');if(!el||el.options.length>1)return;[...new Set(vagasPublicas().map(v=>v.area).filter(Boolean))].sort().forEach(x=>el.add(new Option(x,x)))}function textoDataVaga(v){const d=new Date(v.criadoEm||Date.now()),dias=Math.max(0,Math.floor((Date.now()-d.getTime())/86400000));return dias===0?'Publicada hoje':dias===1?'Publicada ontem':'Publicada há '+dias+' dias'}function textoPrazoVaga(v){if(!v.dataEncerramento)return'';const hoje=new Date();hoje.setHours(0,0,0,0);const fim=new Date(v.dataEncerramento+'T00:00:00'),dias=Math.ceil((fim-hoje)/86400000);if(dias<0)return'Inscrições encerradas';if(dias===0)return'Último dia';if(dias===1)return'Encerra amanhã';return'Encerra em '+dias+' dias'}function vagaDentroPrazo(v){if(!v.dataEncerramento)return true;return new Date(v.dataEncerramento+'T23:59:59')>=new Date()}function destaqueAtivo(v){return !!v.destaque&&(!v.destaqueAte||new Date(v.destaqueAte)>=new Date())}function logoEmpresaVaga(v){if(v.confidencial)return'';const c=nums(v.empresaCnpj||v.cnpj||'');const emp=ler('empregaMaisEmpresas').find(e=>nums(e.cnpj||'')===c);return v.logo||v.logoUrl||v.empresaLogo||emp?.logo||emp?.perfil?.logo||''}
