function adminEmpresaCards(es){if(!es.length)return '<div class="admin-empty">Nenhuma empresa cadastrada.</div>';return es.map(e=>{const p=PLANOS_EMPRESA[e.plano||'basico']||PLANOS_EMPRESA.basico,id=nums(e.cnpj);return '<div class="admin-table-card"><div><h3>'+esc(e.nome||'Empresa')+' '+(e.suspensaAdmin?'<span class="admin-pill">SUSPENSA</span>':'')+'</h3><p>'+esc(e.cnpj||'')+' · Plano '+esc(p.nome)+(e.planoLiberadoAdmin?' · Cortesia ADM':'')+'</p><div class="admin-concessao"><h4>Controle administrativo</h4><div class="admin-form-inline"><select id="adminPlano_'+id+'"><option value="basico">Grátis</option><option value="mensal">Mensal</option><option value="trimestral">Trimestral</option><option value="semestral">Semestral</option><option value="anual">Anual</option></select><select id="adminVigencia_'+id+'"><option value="30">30 dias</option><option value="90">90 dias</option><option value="180">180 dias</option><option value="365">365 dias</option></select><button onclick="adminConcederPlano(\''+esc(e.cnpj||'')+'\')">Liberar plano grátis</button></div></div></div><div class="admin-tools"><button onclick="adminConcederRecurso(\''+esc(e.cnpj||'')+'\',\'destaques\')">+ Destaque</button><button onclick="adminConcederRecurso(\''+esc(e.cnpj||'')+'\',\'urgentes\')">+ Urgente</button><button onclick="adminConcederRecurso(\''+esc(e.cnpj||'')+'\',\'vagas\')">+ Vaga</button><button onclick="adminAlternarEmpresa(\''+esc(e.cnpj||'')+'\')">'+(e.suspensaAdmin?'Reativar':'Suspender')+'</button></div></div>'}).join('')}
function adminCandidatoCards(cs){if(!cs.length)return '<div class="admin-empty">Nenhum candidato cadastrado.</div>';return cs.map(x=>'<div class="admin-table-card"><div><h3>'+esc(x.nome||'Candidato')+' '+(x.premium?'<span class="admin-pill">PREMIUM</span>':'')+'</h3><p>'+esc(x.email||'')+(x.cidade?' · '+esc(x.cidade):'')+'</p></div><div class="admin-tools">'+(x.premium?'<button onclick="adminRemoverPremium(\''+esc(x.email||'')+'\')">Remover Premium</button>':'<button onclick="adminPremiumCandidato(\''+esc(x.email||'')+'\')">Liberar Premium grátis</button>')+'</div></div>').join('')}
